//! `docs/bindings-api.md`: every op-table row, named in every language.

use std::fmt::Write;

use rlx_bind::OpSpec;

use crate::kinds::tidy;

pub fn generate(ops: &[OpSpec]) -> String {
    let mut s = String::from(
        "# Graph builders across languages\n\n\
         <!-- @generated by rlx-bindgen from rlx-bind's op table — do not edit;\n\
         regenerate with `just gen-bindings`. -->\n\n\
         Every row of the op table in `crates/bindings/rlx-bind/src/table.rs`, with\n\
         its name in each binding. Arguments are listed in order; `= x` is the\n\
         default, and `{ … }` is the trailing options group (one object in JS,\n\
         keyword-or-positional parameters in Python, flattened parameters in C and\n\
         Swift). See [`bindings.md`](bindings.md) for how the table becomes each\n\
         binding.\n\n",
    );
    let _ = writeln!(s, "{} ops.\n", ops.len());
    s.push_str("| Python | JS | C | Swift | arguments | returns |\n");
    s.push_str("|--------|----|---|-------|-----------|---------|\n");
    for op in ops {
        let mut py = vec![format!("`{}`", op.name)];
        py.extend(op.py_aliases().iter().map(|a| format!("`{a}`")));
        let js: Vec<String> = op.js_names().iter().map(|n| format!("`{n}`")).collect();
        let pos: Vec<String> = op
            .positional()
            .map(|a| match a.default {
                Some(d) => format!("{}: {} = {}", a.name, a.kind, tidy(d).replace('|', "\\|")),
                None => format!("{}: {}", a.name, a.kind),
            })
            .collect();
        let opts: Vec<String> = op
            .options()
            .map(|a| match a.default {
                Some(d) => format!("{} = {}", a.name, tidy(d).replace('|', "\\|")),
                None => a.name.to_string(),
            })
            .collect();
        let mut args = pos.join(", ");
        if !opts.is_empty() {
            if !args.is_empty() {
                args.push_str(", ");
            }
            let _ = write!(args, "{{ {} }}", opts.join(", "));
        }
        let _ = writeln!(
            s,
            "| {} | {} | `rlx_graph_{}` | `{}` | {} | {} |",
            py.join(", "),
            js.join(", "),
            op.c_name(),
            op.swift_name(),
            args,
            op.ret
        );
    }
    s.push_str("\n## License\n\nMIT OR Apache-2.0.\n");
    s
}
